// Container for storing feature names
$features = []

// Keywords available for combination
$keywords = ['Flow', 'Data', 'Stream', 'View', 'Core']

// Generate all possible unique combinations of the keywords
foreach ($keywords as $k1) {
    foreach ($keywords as $k2) {
        foreach ($keywords as $k3) {
            // Skip if any keyword is repeated within the combination
            // (since you want strictly the given keywords used without repating a single one in a triplet)
            if (count(array_unique([$k1, $k2, $k3])) < 3) continue;

            // Combine keywords with '_' separator and add to list
            $features[] = $k1 . '_' . $k2 . '_' . $k3
        }
